<?php require_once __DIR__.'/../src/db.php';$id=(int)($_GET['id']??0);$q=db()->prepare("SELECT s.*,p.image,p.title panorama_title FROM tour_scenes s JOIN panoramas p ON p.id=s.panorama_id WHERE s.tour_id=? ORDER BY s.sort_order LIMIT 1");$q->execute([$id]);$s=$q->fetch();if(!$s){http_response_code(404);exit('Tour has no scenes');}header('Location:/viewer.php?id='.$s['panorama_id'].'&tour='.$id.'&scene='.$s['id']);